import 'package:setlist_ui/testing.dart';

Future<Uint8List> render(WidgetTester t, String s) async {
  final key = GlobalKey();
  await t.pumpWidget(MaterialApp(home: RepaintBoundary(key: key,
    child: Material(child: Text(s, textDirection: TextDirection.ltr,
      style: const TextStyle(fontSize: 40))))));
  late Uint8List out;
  await t.runAsync(() async {
    final b = key.currentContext!.findRenderObject()! as RenderRepaintBoundary;
    final img = await b.toImage();
    final d = await img.toByteData(format: ui.ImageByteFormat.png);
    out = d!.buffer.asUint8List();
  });
  return out;
}
